def belt_path(pts):
    tiles = []
    for (a,b) in zip(pts[:-1], pts[1:]):
        dx = (b[0]>a[0]) - (b[0]<a[0]); dy = (b[1]>a[1]) - (b[1]<a[1])
        d = Direction.RIGHT if dx>0 else Direction.LEFT if dx<0 else Direction.DOWN if dy>0 else Direction.UP
        x,y = a
        while (x,y) != b:
            tiles.append((x,y,d)); x+=dx; y+=dy
    tiles.append((pts[-1][0], pts[-1][1], tiles[-1][2]))
    n=0
    for i,(x,y,d) in enumerate(tiles):
        if i % 8 == 0: move_to(P(x,y))
        try:
            place_entity(Prototype.TransportBelt, position=P(x,y), direction=d); n+=1
        except Exception as ex:
            print('belt FAIL', x,y, str(ex)[:150])
    print('placed', n, 'of', len(tiles))
